class MyApplication : Application() {
    var isFirstActivityInProcess = true
    override fun onCreate() {
        super.onCreate()
        isFirstActivityInProcess = true
    }
}

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val app = application as MyApplication
        val cold = app.isFirstActivityInProcess   // first Activity in this process
        app.isFirstActivityInProcess = false
        // A warm start = new Activity created in an already-running process;
        // a hot start = same Activity resumed, so onCreate is never called again.
    }
}

// Bad: blocking database I/O on the main thread inside a click handler.
fun onButtonClick() {
    val rows = database.query("SELECT ...")   // ANR bait on a cold cache
    adapter.submitList(rows)
}

// Good: move the work off the main thread.
fun onButtonClick() = lifecycleScope.launch {
    val rows = withContext(Dispatchers.IO) { database.query("SELECT ...") }
    adapter.submitList(rows)
}

class App : Application() {
    var cachedContext: Context? = null      // never stash an Activity here
}

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // LEAK: the singleton outlives the Activity and keeps its whole
        // view tree referenced after finish().
        (application as App).cachedContext = this
    }
}

// A wakelock with a hard timeout — released even if work throws.
val lock = powerManager.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "sync")
lock.acquire(10_000)
try { doSync() } finally { if (lock.isHeld) lock.release() }

// Prefer WorkManager: it batches, defers in Doze, and retries with backoff.
WorkManager.getInstance(context).enqueueUniquePeriodicWork(
    "sync", ExistingPeriodicWorkPolicy.UPDATE,
    PeriodicWorkRequestBuilder<SyncWorker>(15, TimeUnit.MINUTES).build()
)

